import { NBVIEW_MIME } from './constants.js';

/**
 * Parse and validate an nbview MIME directive from a display_data / execute_result output.
 * Returns null if the output does not contain a valid directive.
 */
export function parseNbviewDirective(output) {
  if (!output?.data?.[NBVIEW_MIME]) return null;

  const raw = output.data[NBVIEW_MIME];
  const payload = typeof raw === 'string' ? JSON.parse(raw) : raw;

  if (payload?.version !== 1) return null;
  if (payload.kind === 'slider') {
    if (!Array.isArray(payload.frames) || payload.frames.length === 0) return null;
    return {
      kind: 'slider',
      collapsed: Boolean(payload.collapsed),
      frames: payload.frames.map(normalizeFrame),
    };
  }
  if (payload.kind === 'collapsed' && payload.directive) {
    const nested = parseDirectiveObject(payload.directive);
    if (!nested) return null;
    return { kind: 'collapsed', collapsed: true, nested };
  }
  return null;
}

function parseDirectiveObject(payload) {
  if (payload?.version !== 1) return null;
  if (payload.kind === 'slider') {
    if (!Array.isArray(payload.frames) || payload.frames.length === 0) return null;
    return {
      kind: 'slider',
      collapsed: Boolean(payload.collapsed),
      frames: payload.frames.map(normalizeFrame),
    };
  }
  return null;
}

function normalizeFrame(frame) {
  if (frame.type === 'text') {
    return { type: 'text', data: frame.value };
  }
  if (frame.type === 'image/png' || frame.type === 'image/jpeg') {
    return { type: 'image', mime: frame.type, data: frame.value };
  }
  return frame;
}

export function cellIsCollapsed(cell) {
  const tags = cell?.metadata?.tags;
  return Array.isArray(tags) && tags.includes('nbview-collapsed');
}

export function cellHasLegacyMinimizedMarker(sourceText) {
  const raw = typeof sourceText === 'string' ? sourceText : (Array.isArray(sourceText) ? sourceText.join('') : '');
  const lines = raw.split('\n');
  let i = 0;
  while (i < lines.length && lines[i].trim() === '') i += 1;
  if (i >= lines.length) return { minimizedByDefault: false, code: raw };

  const first = lines[i].trim();
  const isHashComment = first.startsWith('#');
  const isSlashComment = first.startsWith('//');
  if (!isHashComment && !isSlashComment) return { minimizedByDefault: false, code: raw };

  const commentBody = isHashComment ? first.slice(1).trim() : first.slice(2).trim();
  if (commentBody !== 'abhij2706.github.io:minimized') {
    return { minimizedByDefault: false, code: raw };
  }

  const remaining = [...lines.slice(0, i), ...lines.slice(i + 1)].join('\n').replace(/^\n+/, '');
  return { minimizedByDefault: true, code: remaining };
}

export function resolveCellCollapsed(cell, sourceText) {
  if (cellIsCollapsed(cell)) {
    return { minimizedByDefault: true, code: sourceText };
  }
  return cellHasLegacyMinimizedMarker(sourceText);
}
