import React, { useState } from 'react';
import { Box, Typography, Paper } from '@mui/material';

export default function CollapsibleOutput({ minimizedByDefault, label = 'Output', children }) {
  const [open, setOpen] = useState(!minimizedByDefault);
  const toggle = () => setOpen((v) => !v);

  return (
    <Box className="notebook-output" sx={{ marginBottom: 2 }}>
      <Paper
        elevation={0}
        sx={{
          border: '1px solid #ddd',
          borderRadius: 2,
          overflow: 'hidden',
          backgroundColor: '#fafafa',
        }}
      >
        <Box
          onClick={toggle}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') toggle();
          }}
          sx={{
            padding: '0.5rem 1rem',
            borderBottom: open ? '1px solid #ddd' : 'none',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            cursor: 'pointer',
            userSelect: 'none',
          }}
          aria-expanded={open}
        >
          <Typography
            variant="caption"
            sx={{
              color: '#666',
              fontSize: '0.75rem',
              textTransform: 'uppercase',
              letterSpacing: '0.5px',
            }}
          >
            {label}
          </Typography>
          <Typography variant="caption" sx={{ color: '#888', fontSize: '0.8rem' }}>
            {open ? 'Click to hide' : 'Click to view'}
          </Typography>
        </Box>
        {open && <Box sx={{ p: 0.5 }}>{children}</Box>}
      </Paper>
    </Box>
  );
}
