import React, { useState } from 'react';
import { Box, Typography, Paper } from '@mui/material';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { vscDarkPlus } from 'react-syntax-highlighter/dist/esm/styles/prism';
import CollapsibleOutput from './CollapsibleOutput';
import { renderDirective } from './SliderOutput';
import { buildOutputRenderList } from '../directives/legacy.js';
import { parseNbviewDirective } from '../directives/mime.js';

export default function CodeCell({ code, language, outputs, minimizedByDefault, renderOutput }) {
  const [open, setOpen] = useState(!minimizedByDefault);

  const items = buildOutputRenderList(outputs, { parseDirective: parseNbviewDirective });

  return (
    <Box className="notebook-cell notebook-code" sx={{ marginBottom: 4 }}>
      <Paper
        elevation={0}
        sx={{
          backgroundColor: '#1e1e1e',
          borderRadius: 2,
          overflow: 'hidden',
          border: '1px solid #333',
        }}
      >
        <Box
          onClick={() => setOpen((v) => !v)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') setOpen((v) => !v);
          }}
          sx={{
            backgroundColor: '#252526',
            padding: '0.5rem 1rem',
            borderBottom: '1px solid #333',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            cursor: 'pointer',
            userSelect: 'none',
          }}
          aria-expanded={open}
        >
          <Typography
            variant="caption"
            sx={{
              color: '#858585',
              fontSize: '0.75rem',
              textTransform: 'uppercase',
              letterSpacing: '0.5px',
            }}
          >
            {language}
          </Typography>
          <Typography variant="caption" sx={{ color: '#c0c0c0', fontSize: '0.8rem' }}>
            {open ? 'Click to hide' : 'Click to view'}
          </Typography>
        </Box>

        {open && (
          <SyntaxHighlighter
            language={language}
            style={vscDarkPlus}
            customStyle={{
              margin: 0,
              padding: '1rem',
              fontSize: '0.9rem',
              lineHeight: 1.6,
              backgroundColor: '#1e1e1e',
            }}
            showLineNumbers={false}
          >
            {code}
          </SyntaxHighlighter>
        )}
      </Paper>

      {items.length > 0 && (
        <Box sx={{ marginTop: 2 }}>
          {items.map((item, outputIndex) => {
            const content = item.kind === 'slider' || item.kind === 'directive'
              ? renderDirective(item.directive)
              : renderOutput(item.output);
            if (content == null) return null;

            return (
              <CollapsibleOutput
                key={outputIndex}
                minimizedByDefault={item.minimizedByDefault}
                label={item.kind === 'slider' || item.kind === 'directive' ? 'Slider' : 'Output'}
              >
                {content}
              </CollapsibleOutput>
            );
          })}
        </Box>
      )}
    </Box>
  );
}
