import React, { useState } from 'react';
import { Box, Typography } from '@mui/material';

function renderSliderFrame(frame) {
  if (frame.type === 'text') return frame.data;
  if (frame.type === 'image') {
    return (
      <Box
        component="img"
        src={`data:${frame.mime};base64,${frame.data}`}
        alt="Notebook frame"
        sx={{
          maxWidth: 'none',
          width: 'auto',
          height: 'auto',
          borderRadius: 1,
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          display: 'block',
        }}
      />
    );
  }
  return frame?.data ?? '';
}

export default function SliderOutput({ frames }) {
  const [index, setIndex] = useState(0);
  const n = frames.length;
  const current = frames[index];
  const isTextFrame = current?.type === 'text';

  return (
    <Box className="notebook-slider-output" sx={{ marginTop: 1, marginBottom: 2 }}>
      <Box
        component={isTextFrame ? 'pre' : 'div'}
        sx={{
          fontFamily: isTextFrame ? 'monospace' : 'inherit',
          fontSize: '0.9rem',
          lineHeight: 1.6,
          margin: 0,
          padding: isTextFrame ? 2 : 0,
          backgroundColor: isTextFrame ? '#f5f5f5' : 'transparent',
          borderRadius: 1,
          whiteSpace: isTextFrame ? 'pre' : 'normal',
          minWidth: 'fit-content',
          minHeight: 60,
          maxHeight: isTextFrame ? 400 : 600,
          overflow: 'auto',
        }}
      >
        {renderSliderFrame(current)}
      </Box>
      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.5, mt: 1.5 }}>
        <Typography variant="body2" sx={{ color: 'text.secondary', minWidth: '2.5rem' }}>
          {index + 1} / {n}
        </Typography>
        <Box
          component="input"
          type="range"
          min={0}
          max={Math.max(0, n - 1)}
          value={index}
          onChange={(e) => setIndex(Number(e.target.value))}
          aria-label="Frame"
          sx={{
            flex: 1,
            height: 6,
            cursor: 'pointer',
            accentColor: '#1e40af',
          }}
        />
      </Box>
    </Box>
  );
}

export function renderDirective(directive) {
  if (!directive) return null;
  if (directive.kind === 'collapsed' && directive.nested) {
    return renderDirective(directive.nested);
  }
  if (directive.kind === 'slider') {
    return <SliderOutput frames={directive.frames} />;
  }
  return null;
}
