import React, { useState, useEffect } from 'react';
import {
  Container,
  Box,
  Typography,
  CircularProgress,
  Alert,
  Link,
} from '@mui/material';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import remarkMath from 'remark-math';
import rehypeKatex from 'rehype-katex';
import 'katex/dist/katex.min.css';
import './NotebookViewer.css';
import CodeCell from './components/CodeCell';
import { parseLegacySliders, parseMinimizedPrefix } from './directives/legacy.js';
import { parseNbviewDirective, resolveCellCollapsed } from './directives/mime.js';
import { renderDirective } from './components/SliderOutput';

const markdownSx = {
  marginBottom: 4,
  textAlign: 'left',
  '& p': {
    marginBottom: '1.5rem',
    lineHeight: 1.8,
    fontSize: '1.1rem',
    color: '#333',
    textAlign: 'left',
  },
  '& h1': {
    marginTop: '2rem',
    marginBottom: '1rem',
    fontSize: '2.5rem',
    fontWeight: 700,
    lineHeight: 1.2,
    textAlign: 'left',
  },
  '& h2': {
    marginTop: '2rem',
    marginBottom: '1rem',
    fontSize: '2rem',
    fontWeight: 600,
    lineHeight: 1.3,
    textAlign: 'left',
  },
  '& h3': {
    marginTop: '1.5rem',
    marginBottom: '0.75rem',
    fontSize: '1.5rem',
    fontWeight: 600,
    lineHeight: 1.4,
    textAlign: 'left',
  },
  '& ul, & ol': { marginBottom: '1.5rem', paddingLeft: '2rem' },
  '& li': { marginBottom: '0.5rem', lineHeight: 1.8 },
  '& blockquote': {
    borderLeft: '4px solid #1e40af',
    paddingLeft: '1.5rem',
    marginLeft: 0,
    marginBottom: '1.5rem',
    fontStyle: 'italic',
    color: '#666',
  },
  '& code': {
    backgroundColor: '#f5f5f5',
    padding: '0.2em 0.4em',
    borderRadius: '3px',
    fontSize: '0.9em',
    fontFamily: 'monospace',
  },
  '& pre': {
    backgroundColor: '#f5f5f5',
    padding: '1rem',
    borderRadius: '8px',
    overflowX: 'auto',
    marginBottom: '1.5rem',
  },
  '& pre code': { backgroundColor: 'transparent', padding: 0 },
  '& table': { width: '100%', borderCollapse: 'collapse', marginBottom: '1.5rem' },
  '& th, & td': { border: '1px solid #ddd', padding: '0.75rem', textAlign: 'left' },
  '& th': { backgroundColor: '#f5f5f5', fontWeight: 600 },
  '& img': {
    maxWidth: '100%',
    height: 'auto',
    borderRadius: '8px',
    marginTop: '1rem',
    marginBottom: '1rem',
  },
  '& a': {
    color: '#1e40af',
    textDecoration: 'none',
    '&:hover': { textDecoration: 'underline' },
  },
};

function NotebookViewer({
  notebookPath,
  notebookData = null,
  title: titleOverride = null,
  backLink = null,
  maxWidth = 'md',
  fontFamily = "'Source Serif 4', serif",
}) {
  const [notebook, setNotebook] = useState(notebookData);
  const [loading, setLoading] = useState(Boolean(notebookPath && !notebookData));
  const [error, setError] = useState(null);

  useEffect(() => {
    if (notebookData) {
      setNotebook(notebookData);
      setLoading(false);
      return undefined;
    }

    if (!notebookPath) {
      setLoading(false);
      return undefined;
    }

    let cancelled = false;
    const loadNotebook = async () => {
      try {
        setLoading(true);
        setError(null);
        const response = await fetch(notebookPath);
        if (!response.ok) {
          throw new Error(`Failed to load notebook: ${response.statusText}`);
        }
        const data = await response.json();
        if (!data.cells || !Array.isArray(data.cells)) {
          throw new Error('Invalid notebook format: missing cells array');
        }
        if (!cancelled) setNotebook(data);
      } catch (err) {
        if (!cancelled) {
          setError(err.message);
          console.error('Error loading notebook:', err);
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    };

    loadNotebook();
    return () => { cancelled = true; };
  }, [notebookPath, notebookData]);

  const renderOutput = (output) => {
    if (!output) return null;

    const mimeDirective = parseNbviewDirective(output);
    if (mimeDirective) return renderDirective(mimeDirective);

    const outputType = output.output_type;
    const data = output.data || {};

    if (outputType === 'stream') {
      const text = output.text || '';
      const streamText = Array.isArray(text) ? text.join('') : text;
      const { text: strippedText } = parseMinimizedPrefix(streamText);
      const sliders = parseLegacySliders(strippedText);
      if (sliders) {
        return (
          <Box sx={{ maxHeight: '400px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
            {sliders.map((directive, i) => (
              <React.Fragment key={i}>{renderDirective(directive)}</React.Fragment>
            ))}
          </Box>
        );
      }
      return (
        <Box sx={{ marginTop: 1, maxHeight: '400px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
          <Box
            component="pre"
            sx={{
              fontFamily: 'monospace',
              fontSize: '0.9rem',
              lineHeight: 1.6,
              margin: 0,
              padding: 2,
              backgroundColor: '#f5f5f5',
              borderRadius: 1,
              whiteSpace: 'pre',
              minWidth: 'fit-content',
            }}
          >
            {strippedText}
          </Box>
        </Box>
      );
    }

    if (outputType === 'error') {
      const traceback = output.traceback || [];
      const errorName = output.ename || 'Error';
      const errorValue = output.evalue || '';
      return (
        <Box
          sx={{
            backgroundColor: '#fee',
            borderLeft: '4px solid #f44336',
            padding: 2,
            borderRadius: 1,
            marginTop: 1,
            maxHeight: '400px',
            overflowY: 'auto',
            overflowX: 'auto',
          }}
        >
          <Typography variant="subtitle2" sx={{ color: '#c62828', fontWeight: 600, mb: 1, fontFamily }}>
            {errorName}: {errorValue}
          </Typography>
          {traceback.length > 0 && (
            <Box
              component="pre"
              sx={{
                fontFamily: 'monospace',
                fontSize: '0.85rem',
                margin: 0,
                whiteSpace: 'pre',
                color: '#c62828',
                minWidth: 'fit-content',
              }}
            >
              {traceback.join('\n')}
            </Box>
          )}
        </Box>
      );
    }

    if (outputType === 'execute_result' || outputType === 'display_data') {
      if (data['image/png']) {
        return (
          <Box sx={{ marginTop: 1, textAlign: 'left', maxHeight: '600px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
            <img
              src={`data:image/png;base64,${data['image/png']}`}
              alt="Notebook output"
              style={{
                maxWidth: 'none',
                width: 'auto',
                height: 'auto',
                borderRadius: 8,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                display: 'block',
              }}
            />
          </Box>
        );
      }

      if (data['image/jpeg'] || data['image/jpg']) {
        const imageData = data['image/jpeg'] || data['image/jpg'];
        return (
          <Box sx={{ marginTop: 1, textAlign: 'left', maxHeight: '600px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
            <img
              src={`data:image/jpeg;base64,${imageData}`}
              alt="Notebook output"
              style={{
                maxWidth: 'none',
                width: 'auto',
                height: 'auto',
                borderRadius: 8,
                boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
                display: 'block',
              }}
            />
          </Box>
        );
      }

      if (data['text/html']) {
        const html = Array.isArray(data['text/html']) ? data['text/html'].join('') : data['text/html'];
        return (
          <Box
            sx={{
              marginTop: 1,
              maxHeight: '600px',
              overflowY: 'auto',
              overflowX: 'auto',
              borderRadius: 1,
              '& img': { maxWidth: 'none', width: 'auto', height: 'auto', borderRadius: 1 },
            }}
            dangerouslySetInnerHTML={{ __html: html }}
          />
        );
      }

      if (data['text/plain']) {
        let text = Array.isArray(data['text/plain']) ? data['text/plain'].join('') : data['text/plain'];
        const { text: strippedText } = parseMinimizedPrefix(text);
        text = strippedText;

        if (typeof text === 'string' && text.trim().match(/^<Figure size \d+x\d+ with \d+ Axes>$/)) {
          return null;
        }

        const sliders = parseLegacySliders(text);
        if (sliders) {
          return (
            <Box sx={{ marginTop: 1, maxHeight: '400px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
              {sliders.map((directive, i) => (
                <React.Fragment key={i}>{renderDirective(directive)}</React.Fragment>
              ))}
            </Box>
          );
        }

        return (
          <Box sx={{ marginTop: 1, maxHeight: '400px', overflowY: 'auto', overflowX: 'auto', borderRadius: 1 }}>
            <Box
              component="pre"
              sx={{
                fontFamily: 'monospace',
                fontSize: '0.9rem',
                lineHeight: 1.6,
                margin: 0,
                padding: 2,
                backgroundColor: '#f5f5f5',
                borderRadius: 1,
                whiteSpace: 'pre',
                minWidth: 'fit-content',
              }}
            >
              {text}
            </Box>
          </Box>
        );
      }

      if (data['text/latex']) {
        const latex = Array.isArray(data['text/latex']) ? data['text/latex'].join('') : data['text/latex'];
        return (
          <Box sx={{ marginTop: 1, padding: 2, backgroundColor: '#f5f5f5', borderRadius: 1, maxHeight: '400px', overflowY: 'auto', overflowX: 'auto' }}>
            <ReactMarkdown remarkPlugins={[remarkMath]} rehypePlugins={[rehypeKatex]}>
              {`$$${latex}$$`}
            </ReactMarkdown>
          </Box>
        );
      }
    }

    return null;
  };

  const renderCell = (cell, index) => {
    const cellType = cell.cell_type;
    const source = cell.source || '';
    const sourceText = Array.isArray(source) ? source.join('') : source;

    if (cellType === 'markdown') {
      return (
        <Box key={index} className="notebook-cell notebook-markdown" sx={markdownSx}>
          <ReactMarkdown remarkPlugins={[remarkGfm, remarkMath]} rehypePlugins={[rehypeKatex]}>
            {sourceText}
          </ReactMarkdown>
        </Box>
      );
    }

    if (cellType === 'code') {
      const outputs = cell.outputs || [];
      const language = cell.metadata?.language || 'python';
      const { minimizedByDefault, code } = resolveCellCollapsed(cell, sourceText);

      return (
        <Box key={index}>
          <CodeCell
            code={code}
            language={language}
            outputs={outputs}
            minimizedByDefault={minimizedByDefault}
            renderOutput={renderOutput}
          />
        </Box>
      );
    }

    if (cellType === 'raw') {
      return (
        <Box
          key={index}
          className="notebook-cell notebook-raw"
          sx={{
            marginBottom: 4,
            padding: 2,
            backgroundColor: '#f9f9f9',
            borderRadius: 1,
            border: '1px solid #e0e0e0',
          }}
        >
          <Typography variant="caption" sx={{ display: 'block', marginBottom: 1, color: '#666', fontWeight: 600, fontFamily }}>
            Raw Cell
          </Typography>
          <Box component="pre" sx={{ fontFamily: 'monospace', fontSize: '0.9rem', margin: 0, whiteSpace: 'pre-wrap', wordBreak: 'break-word' }}>
            {sourceText}
          </Box>
        </Box>
      );
    }

    return null;
  };

  const backLinkNode = backLink ? (
    typeof backLink === 'string' ? (
      <Link href={backLink} sx={{ position: 'absolute', top: 16, left: 16, color: '#1e40af', textDecoration: 'none', fontFamily, fontSize: '1rem', '&:hover': { textDecoration: 'underline' } }}>
        ← Back
      </Link>
    ) : backLink
  ) : null;

  if (loading) {
    return (
      <Container maxWidth={maxWidth} sx={{ py: 8, textAlign: 'left', position: 'relative' }}>
        {backLinkNode}
        <CircularProgress />
        <Typography variant="body1" sx={{ mt: 2, color: 'text.secondary', fontFamily }}>
          Loading notebook...
        </Typography>
      </Container>
    );
  }

  if (error) {
    return (
      <Container maxWidth={maxWidth} sx={{ py: 8, position: 'relative' }}>
        {backLinkNode}
        <Alert severity="error">
          <Typography variant="h6" gutterBottom sx={{ fontFamily }}>Error loading notebook</Typography>
          <Typography variant="body2" sx={{ fontFamily }}>{error}</Typography>
        </Alert>
      </Container>
    );
  }

  if (!notebook) {
    return (
      <Container maxWidth={maxWidth} sx={{ py: 8, position: 'relative' }}>
        {backLinkNode}
        <Alert severity="info">
          <Typography sx={{ fontFamily }}>No notebook provided.</Typography>
        </Alert>
      </Container>
    );
  }

  const metadata = notebook.metadata || {};
  const title = titleOverride || metadata.title || 'Notebook';

  return (
    <Container maxWidth={maxWidth} className="notebook-viewer" sx={{ py: { xs: 4, md: 6 }, textAlign: 'left', position: 'relative' }}>
      {backLinkNode}
      <Box sx={{ mb: 6, mt: 6, pt: 2, textAlign: 'center' }}>
        <Typography variant="h3" component="h1" sx={{ fontWeight: 700, marginBottom: 2, color: '#1e40af', lineHeight: 1.2, textAlign: 'center', fontFamily }}>
          {title}
        </Typography>
        {metadata.authors && (
          <Typography variant="body1" color="text.secondary" sx={{ mb: 1, textAlign: 'center', fontFamily }}>
            {Array.isArray(metadata.authors) ? metadata.authors.join(', ') : metadata.authors}
          </Typography>
        )}
        {metadata.date && (
          <Typography variant="body2" color="text.secondary" sx={{ textAlign: 'center', fontFamily }}>
            {new Date(metadata.date).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })}
          </Typography>
        )}
      </Box>
      <Box className="notebook-content" sx={{ textAlign: 'left' }}>
        {notebook.cells.map((cell, index) => renderCell(cell, index))}
      </Box>
    </Container>
  );
}

export default NotebookViewer;
