import { LEGACY, joinOutputText } from './constants.js';

function parseFramesFromBlock(blockContent) {
  const parts = blockContent.split(LEGACY.FRAME_START);
  const frames = [];
  for (let i = 1; i < parts.length; i += 1) {
    const chunk = parts[i];
    const endIdx = chunk.indexOf(LEGACY.FRAME_END);
    const content = endIdx >= 0 ? chunk.slice(0, endIdx).trim() : chunk.trim();
    frames.push({ type: 'text', data: content });
  }
  return frames;
}

export function parseLegacySliders(text) {
  const raw = joinOutputText(text);
  let remaining = raw;
  const sliders = [];
  while (remaining.includes(LEGACY.SLIDER_START)) {
    const idx = remaining.indexOf(LEGACY.SLIDER_START);
    const afterShebang = remaining.slice(idx + LEGACY.SLIDER_START.length);
    const endIdx = afterShebang.indexOf(LEGACY.SLIDER_END);
    if (endIdx < 0) break;
    const blockContent = afterShebang.slice(0, endIdx);
    const frames = parseFramesFromBlock(blockContent);
    if (frames.length > 0) sliders.push({ kind: 'slider', collapsed: false, frames });
    remaining = afterShebang.slice(endIdx + LEGACY.SLIDER_END.length);
  }
  return sliders.length > 0 ? sliders : null;
}

export function parseMinimizedPrefix(text) {
  const raw = joinOutputText(text);
  const trimmed = raw.trimStart();
  if (!trimmed.startsWith(LEGACY.MINIMIZED)) {
    return { minimizedByDefault: false, text: raw };
  }
  let rest = trimmed.slice(LEGACY.MINIMIZED.length);
  if (rest.startsWith('\r\n')) rest = rest.slice(2);
  else if (rest.startsWith('\n')) rest = rest.slice(1);
  return { minimizedByDefault: true, text: rest };
}

export function isMinimizedMarkerOnly(text) {
  return joinOutputText(text).trim() === LEGACY.MINIMIZED;
}

export function stripMinimizedFromOutput(output) {
  if (!output) return output;
  if (output.output_type === 'stream') {
    const { text } = parseMinimizedPrefix(output.text);
    return { ...output, text };
  }
  if (output.data?.['text/plain']) {
    const { text } = parseMinimizedPrefix(output.data['text/plain']);
    return { ...output, data: { ...output.data, 'text/plain': text } };
  }
  return output;
}

/**
 * Matplotlib plt.show() emits display_data between stream markers. Detect that
 * interleaved pattern starting at outputs[startIndex] and return image frames.
 */
export function parseInterleavedLegacySliderAt(outputs, startIndex) {
  const out = outputs[startIndex];
  if (!out || out.output_type !== 'stream') return null;
  const { text, minimizedByDefault } = parseMinimizedPrefix(out.text);
  if (!text.includes(LEGACY.SLIDER_START) || !text.includes(LEGACY.FRAME_START)) return null;

  const frames = [];
  let i = startIndex + 1;

  const readImageFrame = () => {
    if (i >= outputs.length || outputs[i].output_type !== 'display_data') return false;
    const png = outputs[i].data?.['image/png'];
    if (!png) return false;
    frames.push({ type: 'image', mime: 'image/png', data: png });
    i += 1;
    return true;
  };

  if (!readImageFrame()) return null;

  while (i < outputs.length) {
    if (outputs[i].output_type !== 'stream') return null;
    const streamText = joinOutputText(outputs[i].text);
    if (streamText.includes(LEGACY.SLIDER_END)) {
      return frames.length > 0 ? { kind: 'slider', collapsed: false, frames, endIndex: i, minimizedByDefault } : null;
    }
    if (!streamText.includes(LEGACY.FRAME_START)) return null;
    i += 1;
    if (!readImageFrame()) return null;
  }

  return null;
}

export function buildOutputRenderList(outputs, { parseDirective }) {
  const items = [];
  let i = 0;
  while (i < outputs.length) {
    let minimizedByDefault = false;
    if (outputs[i].output_type === 'stream' && isMinimizedMarkerOnly(outputs[i].text)) {
      minimizedByDefault = true;
      i += 1;
      if (i >= outputs.length) break;
    }

    const directive = parseDirective(outputs[i]);
    if (directive) {
      items.push({
        kind: directive.kind === 'collapsed' ? 'directive' : 'slider',
        directive,
        minimizedByDefault: minimizedByDefault || directive.collapsed,
      });
      i += 1;
      continue;
    }

    const interleaved = parseInterleavedLegacySliderAt(outputs, i);
    if (interleaved) {
      items.push({
        kind: 'slider',
        directive: interleaved,
        minimizedByDefault: minimizedByDefault || interleaved.minimizedByDefault,
      });
      i = interleaved.endIndex + 1;
      continue;
    }

    const out = outputs[i];
    const legacySliders = out.output_type === 'stream'
      ? parseLegacySliders(out.text)
      : out.data?.['text/plain']
        ? parseLegacySliders(out.data['text/plain'])
        : null;

    if (legacySliders) {
      legacySliders.forEach((sliderDirective) => {
        items.push({
          kind: 'slider',
          directive: sliderDirective,
          minimizedByDefault,
        });
      });
      i += 1;
      continue;
    }

    const { minimizedByDefault: prefixMinimized } = parseMinimizedPrefix(
      out.output_type === 'stream' ? out.text : out.data?.['text/plain'],
    );
    items.push({
      kind: 'output',
      output: stripMinimizedFromOutput(out),
      minimizedByDefault: minimizedByDefault || prefixMinimized,
    });
    i += 1;
  }
  return items;
}
